def strategy(history, rng):
    n = len(history)
    _ = rng
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'

    forgiven = punished = 0
    rforg = rpuh = 0
    start = max(0, n - 12)

    for i in range(1, n):
        if my[i - 1] == 'D':
            if opp[i] == 'C':
                forgiven += 1
                if i >= start:
                    rforg += 1
            else:
                punished += 1
                if i >= start:
                    rpuh += 1

    tail_len = min(10, n)
    tail = opp[-tail_len:]
    tail_c = sum(1 for x in tail if x == 'C')

    last_me, last_opp = history[-1]

    exploitable = False
    if opp_d * 2 <= n and tail_c >= tail_len - 2:
        if punished == 0 and forgiven >= 1:
            exploitable = True
        elif rforg >= 2 and rpuh == 0:
            exploitable = True

    if exploitable:
        if last_opp == 'C':
            return 'D'
        if opp_d * 2 <= n:
            return 'C'
        return 'D'

    if opp_d * 4 <= n and n >= 70 and last_opp == 'C' and forgiven == 0 and punished == 0:
        return 'C' if last_me == 'D' else 'D'

    if last_opp == 'D':
        if opp_d * 2 >= n:
            return 'D'
        if n >= 2 and my[-2] == 'D' and opp_d * 4 <= n * 3:
            return 'C'
        return 'D'

    if opp_d * 2 >= n:
        return 'D'

    return 'C'
